INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62662470', 62662470, 'analyze_legacy', 'Mahkamah Agung', 'central', 'BADAN PENGAWASAN MAHKAMAH AGUNG RI', 'Belanja Langganan Internet TA 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 500000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Bulan', 'Langganan Internet Fiber Optik Keperluan Operasional Perkantoran', '1. Menyediakan Minimum Bandwidth Dedicated dengan rasio Upstream Downstream 1:1 untuk media komunikasi Fiber Optik akses ke ke IX (International) dan IIX (Domestic) Pusat terdekat tidak lebih dari 3 HOP. 2. Menyediakan IP Publik sesuai kelas Banwidth yang disewa 3. Menyediakan koneksi akhir menggunakan Ethernet (RJ45). 4. Menyediakan semua akses port terbuka. 5. Menyediakan ketersediaan dan informasi Redundancy Backbone. 6. Menyediakan report utilisasi bandwidth yang dapat dilihat secara langsung untuk link international dan domestic kepada pelanggan. 7. Menyediakan perawatan, dukungan dan pelayanan 24x7 baik online maupun onsite. 8. Menyediakan minimum ketersediaan network 99,9% setiap bulannya untuk FO. 9. Menyediakan laporan bulanan mengenai performance dan penggunaan (traffic) bandwidth internet. Laporan terdiri dari penggunaan traffic bits perdetik. 10. Menyediakan contact service, sistem trouble ticketing dan eskalasi prosedur penanganan masalah yang jelas 11. Menyediakan dokumen meliputi Detail instalasi, Gambar Jaringan yang diinstall, IP Management yang diberikan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 730026);
