INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62596822', 62596822, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK', 'Pengadaan Tenaga Ahli Programmer 1 Pengembangan Aplikasi e-Office', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 42900000, 'March 2026', 'APBD', 1, 1, '1 Orang x 3 Bulan', '1) Mempelajari konsep rancangan dan spesifikasi program, sesuai spesifikasi program yang telah dibuat; 2) Membuat modul-modul pemrograman yang terstruktur sesuai dengan spesifikasi yang dibutuhkan; 3) Mengidentifikasi adanya bug dalam aplikasi; 4) Melakukan Unit Test, Integration Test, serta mendampingi User Acceptance Test setelah modul-modul dalam Aplikasi dapat digunakan; 5) Melakukan tes skenario pada aplikasi web dan aplikasi mobile; 6) Melakukan debugging dan fixing terhadap program-program yang masih perlu diperbaiki; 7) Membuat repository untuk menunjang kegiatan yang dilakukan dalam point 2) di atas; 8) Melakukan integrasi dengan Sistem atau Aplikasi lainnya; 9) Memberikan dukungan teknis dalam troubleshooting; 10) Menyediakan seluruh dokumentasi teknis terkait pengembangan Aplikasi e-Office; 11) Memberikan pelatihan terhadap user dan transfer knowledge terhadap Tim Pendamping Diskominfotik Provinsi DKI Jakarta; 12) Membuat laporan sesuai tahapan pelaksanaan pekerjaan termasuk pendampingan dan konsultasi.', 'S1 Pengalaman Minimal 6 Tahun', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 731521);
