INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62598838', 62598838, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Sewa Kendaraan Jemputan Pada Ditjen Kekayaan Intelektual DKI Jakarta T.A 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 8823937000, 'December 2025', 'APBN - PNBP (D)', 1, 1, '1 Paket (8 bulan)', 'Terlaksananya Pengadaan Sewa Kendaraan Jemputan Pada Ditjen Kekayaan Intelektual DKI Jakarta T.A 2026', 'Kegiatan penyewaan Kendaraan Jemputan terdiri dari kegiatan penyewaan micro bus hiace dengan kapasitas minimal 14 orang dari penyedia jasa dan micro bus elf kapasitas minimal 17 orang dan bus sedang dengan kapasitas minimal 30 orang. Selama masa penyewaan, penyedia wajib menyediakan sarana antar jemput pegawai dua kali sehari, pagi dan sore hari, kecuali hari libur. Untuk hari libur atau hari tertentu yang diwajibkan pegawai untuk hadir di kantor atau tempat yang telah ditentukan oleh DJKI penyedia juga wajib menyediakan sarana antar jemput pegawai tersebut. Untuk hari libur kendaraan menjadi kewenangan Direktorat Jenderal Kekayaan lntelektual dan wajib melaporkan posisi parkir kendaraan tersebut. Jam keberangkatan pada titik jemputan sedemikian rupa sehingga sampai di kantor sebelum jam 07.30, dan keberangkatan dari kantor segera setelah jam 16.10 (Senin -Kamis) atau 16.40 (Jumat). Penyedia wajib menjamin ketersediaan kendaraan sesuai spesifikasi yang telah disyaratkan. Jika terjadi kerusakan, maka penyedia wajib menyediakan pengganti sesegera mungkin atau menggunakan transportasi lain yang dimungkinkan. Pada saat kerusakan terjadi sebelum atau sesudah penjemputan-pengantaran, maka penyedia wajib memberikan kendaraan pengganti sehingga pegawai tetap terlayani sesuai dengan jadwal. Adapun pada saat kerusakan terjadi selama kegiatan penjemputan-pengantaran, maka penyedia wajib memberikan sarana pengganti dalam kurun waktu selambatnya 1 (satu) jam sejak peristiwa kerusakan. Kendaraan jemputan tersebut dapat ditempel stiker untuk keperluan diseminasi informasi Direktorat Jenderal Kekayaan lntelektual. Spesifikasi teknis kendaraan yang disewakan Adalah : A. Bus sedang Sebanyak 8 unit Kapasitas kursi minimum 30 orang; Memiliki pendingin yang maksimal (Full AC); Kursi penumpang yang dapat disesuaikan (reclining seat); Audio Video (LCD TV , DVD Player dan Microfon; Tahun registrasi dan atau pembuatan minimal tahu n 2022; Plat Nomor kendaraan bermotor umum; Memenuhi standar peralatan keselamatan dan keadaan darurat. dibuktikan dengan STNK; B. Micro bus Elf sebanyak 14 kendaraan Kapasitas kursi minimum 17 orang penumpang; Memiliki pendingin yang maksimal (Full AC); Audio Video (LCD TV, DVD Player dan Microfon); Tahun registrasi dan atau pembuatan minimal tahun 2022; Plat Nomor kendaraan bermotor umum; Memenuhi standar peralatan keselamatan dan keadaan darurat. dibuktikan dengan STNK; C. Micro bus Hiace sebanyak 4 unit Kendaraan Kapasitas kursi minimum 14 orang penumpang; Memiliki pendingin yang maksimal (Full AC); Audio Video (LCD TV, DVD Player dan Microfon); Tahun registrasi dan atau pembuatan minimal tahun 2022 Plat Nomor kendaraan bermotor umum; Memenuhi standar peralatan keselamatan dan keadaan darurat. dibuktikan dengan STNK;', 2205984250, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 737048);
