INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63181889', 63181889, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Pemeliharaan E-Report Industri Farmasi', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 42500000, 'July 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1, PT, @ 42500000 )', '1. Pemeliharaan E-Report Industri Farmasi ( 1, PT, @ 42500000 );', 'Kegiatan Pemeliharaan E-Report Industri Farmasi meliputi: 1. Pemeliharaan Modul Master a. Menyempurnakan Integrasi Modul Master Produk dan Master Bahan Baku dengan data base bahan baku obat dan produk obat pada Kamus Farmasi Obat dan Alat Kesehatan (KFA). b. Menyempurnakan Modul Pemutakhiran Data Industri Farmasi dan Data Apoteker c. Interoperabilitas data terkait pelaporan bahan baku dan produksi obat dan vaksin dari BPOM d. Interoperabilitas data terkait produksi obat dari Industri farmasi dengan sistem e-report yang dilakukan secara komprehensiv dan sesuai dengan perkembangan kebutuhan Direktorat Produksi dan Distribusi Farmasi. 2. Pemeliharaan Modul Pelaporan a. Periode Pelaporan b. Pemeliharaan Pelaporan Monitoring Khusus c. Pemeliharaan Pelaporan Potensi Kekosongan Obat d. Pemeliharaan Pelaporan Pemasukan Bahan Baku Obat (Industri Farmasi Obat Jadi) e. Pemeliharaan Pelaporan Rencana Produksi Obat (Industri Farmasi Obat Jadi) f. Pemeliharaan Pelaporan Produksi, Importasi, Distribusi Obat Jadi (Industri Farmasi Obat Jadi) g. Grafik-grafik yang dapat menggambarkan Realisasi Produksi vs Rencana Produksi Obat 50 KJSU, Impor Bahan Baku Obat (BBO), Produksi Obat, Produksi Bahan Baku, Investasi Industri, Nilai Bahan Baku Obat Berdasarkan Negara Produsen, dan grafik lainnya yang dalam perkembangan kegiatan ini diperlukan Direktorat Produksi dan Distribusi Farmasi. 3. Administrasi a. Penyusunan dan penyampaian laporan progres pelaksanaan pekerjaan ini setiap minggu, dan/atau sesuai permintaan dari Direktorat Produksi dan Distribusi Farmasi, dan laporan akhir pelaksanaan pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 737920);
