INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63159020', 63159020, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PENANGGULANGAN KEBAKARAN DAN PENYELAMATAN', 'Penyediaan Tenaga Ahli Tehnical Support Tahap 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 61050000, 'January 2026', 'APBD', 1, 1, '6 Bulan', '1. Melakukan pengelolaan Aplikasi / Software SIPERIKAR (Sistem Informasi Pemetaan Risiko Kebakaran tingkat RW), 2. Melakukan pengelolaan Aplikasi / Software B-STATUS (status keselamatan kebakaran gedung), 3. Melakukan perbaikan Aplikasi / Software SIPERIKAR dan B-STATUS secara dini (trouble shooting) dan melapor kepada atasannya (PPTK), 4. Melakukan pengetesan pada versi pengembangan Aplikasi / Software SIPERIKAR dan B-STATUS 5. Membuat laporan hasil pengetesan versi pengembangan Aplikasi / Software SIPERIKAR dan B-STATUS 6. Memeriksa integritas data pada aplikasi SIPERIKAR dan B-STATUS 7. Melakukan proses backup database aplikasi SIPERIKAR dan B-STATUS secara berkala 8. Membuat dan melengkapi buku panduan penggunaan aplikasi SIPERIKAR dan B-STATUS 9. Menginput data gedung dan data hasil inspeksi keselamatan kebakaran gedung, 10. Melaporkan segera kepada atasannya (PPTK) bila ada software/sistem aplikasi yang bermasalah termasuk rekomendasi tindakan', '1. Memiliki pengalaman pada bidang pekerjaan sejenis yang dibuktikan dengan melampirkan surat pengalaman kerja / kontrak kerja. 2. Memiliki Sertifikat yang relevan dibidang IT/ SI. 3. Menguasai Ms Office, OS, Networking (LAN & WAN, Router, Switch, Cabling, Mikrotik) 4. Memiliki kemampuan menyelesaikan Troubleshooting Hardware dan Software 5. Memahami Framework, PHP, Code Igniter, Database Management System 6. Mampu bekerja secara mandiri dan dapat bekerjasama dalam kelompok 7. Bersedia bekerja diluar jam kerja dan dapat dipanggil sewaktu-waktu apabila dibutuhkan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 738639);
