INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62667720', 62667720, 'analyze_legacy', 'Badan Nasional Penanggulangan Terorisme', 'central', 'Badan Nasional Penanggulangan Terorisme', 'Pekerjaan Jasa Keamanan Kantor BNPT', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bogor (Kab.)', 5460000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, 'satu paket', '1. Ruang Lingkup yang menjadi tugas penyedia di antaranya: a. Pengamanan serta pengaturan keamanan di wilayah luar dan di dalam gedung Kantor BNPT Sentul, meliputi: Area Pelatihan Outdoor, Area Parkir, Halaman dan taman di dalam pagar kawasan Kantor BNPT Sentul, Gedung Baladika, Gedung Nenggala, Gedung Pasopati, Gedung Asrama A & B, Gedung Poliklinik, Guest House, Gedung Awignya (BLK), Gedung Biwara (Pusat Analisis dan Pengendalian Krisis); b. Memelihara keamanan dan ketertiban di wilayah luar dan di dalam gedung Kantor BNPT Sentul dari Pedagang Asongan, Pengemis dan Pihak – pihak lainnya yang mengganggu ketertiban; c. Pengamanan Wilayah Kantor BNPT Sentul dari pengunjuk rasa (demonstrasi); dan d. Pengamanan serta penyelamatan seluruh aset atau barang di wilayah Kantor 2. Tenaga Kerja I. Persyaratan tenaga kerja yang ditugaskan dalam pekerjaan ini adalah : a. Mempunyai keterampilan yang baik tentang pekerjaan yang akan dilaksanakan; b. Memahami sopan santun dan dapat menjaga etika kerja; c. Berbadan sehat, berkelakuan baik, jujur dan bertanggung jawab; d. Untuk Chief Usia Maksimal 40 Tahun, memiliki pendidikan minimal S1, memiliki Ijazah Gada Utama dan KTA, memiliki sertifikat pelatihan bela diri serta berpengalaman sebagai chief minimal 2 tahun; e. Komandan Regu Usia Maksimal 38 Tahun, memiliki pendidikan minimal SMA atau yang sederajat, memiliki Ijazah Gada Madya dan KTA, memiliki sertifikat pelatihan bela diri, berpengalaman di bidang keamanan minimal 2 tahun; f. Anggota/Petugas Keamanan wajib usia maksimal 40 tahun, memiliki Ijazah Gada Pratama dan KTA, memiliki sertifikat pelatihan bela diri, serta berpengalaman menjadi petugas keamanan minimal 2 tahun; g. Petugas Administrasi, memiliki pendidikan minimal D3 (diploma 3) ekonomi manajemen/akuntansi, berpengalaman sebagai administrator minimal 2 tahun; h. Seluruh Personil wajib melampirkan Daftar Riwayat Hidup, KTP, Ijazah Pendidikan, SKCK yang masih berlaku, Surat Keterangan Bebas Narkoba dari kepolisian atau Rumah Sakit, Surat Keterangan Sehat. II. Jumlah Tenaga kerja, Upah dan seragam tenaga kerja a. Chief 1 orang; b. Komandan Regu 3 orang; c. Anggota Pengamanan 55 orang; d. Petugas Administrasi 1 orang; e. Seluruh pekerja wajib diikutsertakan dalam program BPJS Ketenagakerjaan dan BPJS Kesehatan; f. Penyedia jasa wajib memberi THR sebesar 1 (satu) bulan Gaji. g. Penyedia jasa wajib menyediakan pakaian kerja (seragam) yang memiliki komponen Produksi Dalam Negeri (PDN) minimal 40% dibuktikan dengan surat pernyataan dari penyedia dan dengan spesifikasi sebagai berikut:  Seragam dinas PDL berbahan American drill warna coklat 1 set;  Baret berbahan laken berwarna biru;  Seragam safari berbahan twist berwarna biru dongker 1 set;  Kaos dalam dengan logo dan identitas perusahaan;  Face body tactical airsoft;  Tactical helm;  Sepatu PDL;  Inspection mirror;  Garret/metal detector;  Rompi lalu lintas;  Jas hujan;  Sepatu boots;  Alat komunikasi (HT). h. Pengawas dan pelaksana wajib mengenakan kartu tanda pengenal pada saat bertugas. III. Laporan Laporan terdiri dari: a. Laporan bulanan;dan b. Laporan akhir pelaksanaan pekerjaan.', 'Calon penyedia juga diharapkan memiliki kualifikasi sebagai berikut: 1. Memiliki NIB (Nomor Induk Berusaha) dengan KBLI (Aktifitas Keamanan Swasta); 2. Surat izin dari Kepolisian Republik Indonesia sebagai Badan Usaha Jasa Penyediaan Tenaga Pengamanan yang masih berlaku; 3. Memiliki pengalaman pada bidang jasa pengamanan yang dapat ditunjukan dari surat referensi kerja atau kontrak; 4. Akta Pendirian Perusahaan dan Perubahan Terakhir; 5. Memiliki pengalaman pada subbidang jasa pengamanan dengan kemampuan dasar ( KD ) sebesar 50 % dari Harga Pagu; 6. Melampirkan Bukti Stor Pajak 3 bulan Terakhir dan pembayaran SPT Tahun 2019 dan Melampirkan Surat Keterangan Fiskal; 7. Memiliki sertifikat kualitas sistem manajemen ISO 9001:2015 yang masih berlaku; 8. Memiliki sertifikat ISO 45001:2018 yang masih berlaku; 9. Terdaftar sebagai anggota KADIN; 10. Terdaftar sebagai anggota BPJS Ketenaga kerjaan; 11. Terdaftar sebagai anggota BPJS Kesehatan; 12. Memiliki Sertifikat dari Asosiasi Badan Usaha Jasa Pengamanan Indonesia; 13. Memiliki NPWP; 14. Surat Keterangan Terdaftar (SKT); 15. Surat Pengukuhan Pengusaha Kena Pajak (SPPKP); 16. Seluruh personil memiliki pengalaman minimal 2 tahun di perusahaan; pendaftar dan dapat dibuktikan dengan menyampaikan surat keterangan HRD.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 739691);
